<template><section class="bio-nexus-page application-settings-page"><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error"><strong>No fue posible cargar la configuracion.</strong><span>{{loadError}}</span></div><header class="bio-nexus-page-header"><div><p class="bio-nexus-page-eyebrow">Configuracion</p><h2>Configuracion de la aplicacion</h2><p class="bio-nexus-page-description">Administra formatos de documentos, plantillas de reportes y parametros de impresion.</p></div><div class="page-actions"><BioNexusActionButton v-if="dirty" variant="secondary" :disabled="saving" @click="discard">Descartar</BioNexusActionButton><BioNexusActionButton v-if="canUpdate" variant="primary" :loading="saving" :disabled="loading||!dirty" @click="save">Guardar cambios</BioNexusActionButton></div></header><div v-if="loading" class="bio-nexus-empty-state">Cargando configuracion...</div><ApplicationSettingsPanel v-else-if="settings" :model="settings" :disabled="!canUpdate||saving"/></section></template><script setup>import{computed,onMounted,ref}from"vue";import ApplicationSettingsPanel from"@/components/application-settings/ApplicationSettingsPanel.vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import{useBioNexusToast}from"@/composables/useBioNexusToast";import{getApplicationSettings,getApplicationSettingsErrorMessage,updateApplicationSettings}from"@/services/applicationSettingsService";import{validateApplicationSettings}from"@/models/applicationSettings";import{useAuthorizationStore}from"@/stores/authorization";const authorization=useAuthorizationStore(),toast=useBioNexusToast(),settings=ref(null),original=ref(""),loading=ref(false),saving=ref(false),loadError=ref("");const canUpdate=computed(()=>authorization.hasPermission("application-settings.update"));const dirty=computed(()=>settings.value!==null&&JSON.stringify(settings.value)!==original.value);function snapshot(){original.value=JSON.stringify(settings.value)}async function load(){loading.value=true;loadError.value="";try{settings.value=await getApplicationSettings();snapshot()}catch(error){loadError.value=getApplicationSettingsErrorMessage(error,"No fue posible cargar la configuracion.");toast.error(loadError.value)}finally{loading.value=false}}function discard(){if(!original.value)return;settings.value=JSON.parse(original.value);toast.info("Los cambios pendientes fueron descartados.")}async function save(){const errors=validateApplicationSettings(settings.value);if(errors.length){toast.error(errors.join(" "));return}saving.value=true;try{settings.value=await updateApplicationSettings(settings.value);snapshot();toast.success("La configuracion de la aplicacion fue actualizada.")}catch(error){toast.error(getApplicationSettingsErrorMessage(error,"No fue posible guardar la configuracion."))}finally{saving.value=false}}onMounted(load);</script><style scoped>.application-settings-page{min-width:0}.page-actions{display:flex;align-items:center;gap:var(--bio-nexus-space-2);flex-wrap:wrap}</style>